WITH left_oracle AS (WITH scoped AS (SELECT q.mktcode,q.tgtcode,q.bizdate,(q.lastPx/10000.0)*q.totalShare AS metric FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate='2026-04-14' AND (q.mktcode=1 AND q.tgtcode BETWEEN '688000' AND '688999')), industry_stat AS (SELECT i.industry_code,MIN(s.metric) AS baseline FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' GROUP BY i.industry_code) SELECT s.mktcode,s.tgtcode,s.bizdate FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode INNER JOIN industry_stat a ON a.industry_code=i.industry_code WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' AND s.metric>a.baseline), right_oracle AS (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic_technical` WHERE bizdate='2026-04-14' AND ABS(ma5-ma20)/NULLIF(GREATEST(ABS(ma5),ABS(ma20)),0)<=0.03), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=10), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=0) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
